//! The `wasm32` test registry for `temper-rust-router`.
//!
//! Generated by `scripts/gen_wasm_test_registry.py`; run it after adding a
//! test to any listed module, and `--check` gates drift in CI.
//!
//! `cargo test`'s libtest harness cannot target `wasm32-unknown-unknown`,
//! so the Worker tier calls each test function individually instead of
//! running a test binary.  This module is the flat, indexable list of them.
//!
//! Only modules that survive `--no-default-features` appear here.  Tests
//! inside `#[cfg(feature = "python")]` modules are structurally absent
//! from a `wasm32` build and cannot be registered here at all.
//!
//! Two exclusion classes apply here, both structural:
//!
//! * `#[cfg(feature = "python")]` modules -- `types`, `types_py_bridge`,
//!   `theta_star`, `loop_extractor` (whole files, gated at their `pub
//!   mod`/`mod` declaration in `lib.rs`), plus every `#[pyfunction]`/
//!   `#[pymodule]` item declared directly in `lib.rs` itself
//!   (`solve_topology_rust`, `audit_result`, `classify_component_rs`,
//!   `astar_kernel_3d_py`, `line_of_sight_py`,
//!   the `#[pymodule] fn temper_rust_router`).  None of these have
//!   `#[test]` of their own that exercises anything beyond the pyo3
//!   boundary itself -- the pure kernels underneath
//!   (`classify_component_py`/`parse_capacitance_py`/`astar_kernel_3d`/
//!   etc.) already live in the registered `temper-rust-router-core`.
//! * `mod proptests` in `lib.rs` (`f32s_from_le_bytes`'s round-trip
//!   properties) uses a dev-dependency, which is not linked into the
//!   ordinary (non-test) build this registry compiles into -- the same
//!   exclusion every other crate on the tier makes.
//!
//! `scripts/gen_wasm_test_registry.py --crate temper-rust-router
//! --census` prints the full module census with per-module counts.
//!
//! ## Families
//!
//! Each module entry in `ALL` is gated on a `wasm-registry-<family>`
//! feature, as in `temper-drc-rs`.  One family (`rust-router`): the
//! three surviving modules (`layer_assignment`, `terminal_planning`,
//! `net_ordering`) are a flat set of pure topology kernels with no
//! rule-family taxonomy to shard along.

/// A single test: its fully qualified name and a nullary callable.
///
/// Failure is signalled by panicking, exactly as under libtest.  On
/// `wasm32-unknown-unknown` a panic aborts (the target has no unwinding on
/// stable), which surfaces to the host as a WebAssembly trap -- so the
/// runner catches the trap rather than a `Result`.
pub type WasmTest = (&'static str, fn());

/// All 20 eligible tests, in a stable order.  Each entry is
/// gated on the per-family `wasm-registry-<family>` feature; enable
/// all families (`wasm-test-registry`) or individual ones.
pub const ALL: &[&[WasmTest]] = &[
    #[cfg(feature = "wasm-registry-rust-router")] crate::layer_assignment::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-rust-router")] crate::net_ordering::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-rust-router")] crate::terminal_planning::tests::WASM_TESTS,
];

/// Total number of registered tests *in the currently-selected families*.
pub fn count() -> usize {
    ALL.iter().map(|m| m.len()).sum()
}

/// The test at `index` in the flattened registry.
pub fn get(index: usize) -> Option<&'static WasmTest> {
    let mut remaining = index;
    for module in ALL {
        if remaining < module.len() {
            return Some(&module[remaining]);
        }
        remaining -= module.len();
    }
    None
}
